#pragma once

// Tube Lab presets (1.19.0; tone stack and re-levelled for the new power amp in 1.20.0; re-voiced in
// 1.63.0): every Tube Lab sound param, so a preset fully sets the stage (not its On switch or whether
// it's in the chain). 1.63.0 voiced them at the level the Tube Lab really gets here (hard picks peaking
// around -19 dBFS, soft ones -31; they'd been set with a ~9 dB hotter signal, so at a real playing
// level the drive presets were under-driven and their levels jumped by up to 16 dB), toward targets for
// each name (how much they break up on a hard and a soft pick, low end and top through a 4x12 IR), and
// each Output matches its RMS to the dry signal's on a pickup-filtered strum (Tight Boost: +6 dB, it's
// a boost). Needs the EParams enum (include after NeuralAmpModeler.h).
//
// Enum params are indices: Cap / Cap 2: 0 None, 1 0.68uF, 2 1uF, 3 2.2uF, 4 10uF, 5 25uF;
// Plate Cap / Plate Cap 2: 0 None, 1 47p, 2 100p, 3 220p, 4 470p, 5 1n;
// Couple: 0 2.2n, 1 4.7n, 2 10n, 3 22n, 4 47n, 5 100n.

struct TubePreset
{
  const char* name;
  const char* description;
  struct
  {
    int param;
    double value;
  } values[30];
};

